"""Builds cycle 22 theme-unlockless-frames.research.json from raw/summary-*.json, raw/weak-*.json, raw/w3-*.json and
raw/probe.json. Prose is written here; numbers are read from the raw files."""
import json, os
W = os.path.join(os.path.dirname(__file__), '..')
R = lambda p: json.load(open(os.path.join(W, 'raw', p)))
ALL = [n['chainId'] for n in json.load(open(os.path.join(W, '..', '..', '..', 'state', 'networks.json')))['networks']]
