S = {c: R('summary-%d.json' % c) for c in (999, 4326, 143, 43114)}
WK = {c: R('weak-%d.json' % c) for c in (5042, 99901)}
W3 = {c: R('w3-%d.json' % c) for c in (5042, 99901)}
P = R('probe.json')
WD = 'research/network-risk/cycles/022/theme-unlockless-frames.work'


def fmt(n): return '{:,}'.format(n)


def served(cid):
    p = P[str(cid)]; ok = []; ref = []
    for u, e in p['endpoints'].items():
        m = [k for k in ('debug_traceTransaction_callTracer', 'trace_transaction', 'trace_block', 'debug_traceBlockByNumber_callTracer') if e.get(k, {}).get('ok')]
        cv = e['clientVersionAfter'][0] or e['clientVersionBefore'][0] or 'no version'
        (ok if m else ref).append('%s (%s): %s' % (u, cv, ', '.join(m) if m else 'refuses all four, ' + '; '.join(sorted({(e.get(k) or {}).get('err', '')[:70] for k in ('debug_traceTransaction_callTracer', 'trace_block') if not (e.get(k) or {}).get('ok')}))))
    for u, e in (p.get('extraEndpoints') or {}).items():
        m = [k for k in ('debug_traceTransaction', 'trace_transaction', 'debug_traceBlockByNumber') if isinstance(e.get(k), (list, tuple)) and e[k][0] == 'ok']
        ok.append('%s (%s): %s' % (u, (e.get('cv2') or [None])[0], ', '.join(m))) if m else ref.append(u)
    return ok, ref


